-- 31 Oct 2026 (Sai): the condition deadline reminder asks for the document.
-- Moves the stored email to the new wording ONLY while it still holds the wording the app shipped -
-- an edited template is left exactly as it is. Data only; safe to run twice.
UPDATE "email_templates"
SET "body_html" = $new$<p>Hello {{ agent_name }},</p><p>{{ condition_sentence }} Upload the signed Waiver or Notice of Fulfilment, or an Amendment if the deadline is being extended.</p><table style="border-collapse:collapse;font-size:14px;margin:10px 0"><tr><td style="padding:4px 14px 4px 0;color:#6b7280">Transaction</td><td style="padding:4px 0;font-weight:600">{{ deal_number }}</td></tr><tr><td style="padding:4px 14px 4px 0;color:#6b7280">Property</td><td style="padding:4px 0;font-weight:600">{{ property_address }}</td></tr><tr><td style="padding:4px 14px 4px 0;color:#6b7280">Conditions</td><td style="padding:4px 0;font-weight:600">{{ condition_list }}</td></tr><tr><td style="padding:4px 14px 4px 0;color:#6b7280">Deadline</td><td style="padding:4px 0;font-weight:600">{{ deadline_date }}</td></tr><tr><td style="padding:4px 14px 4px 0;color:#6b7280">Days remaining</td><td style="padding:4px 0;font-weight:600">{{ days_remaining }}</td></tr></table>{{ transaction_button }}<p>{{ company_name }}</p>$new$
WHERE "event_key" = 'transaction.condition_deadline_reminder'
  AND "body_html" = $old$<p>Hello {{ agent_name }},</p><p>{{ condition_count }} condition(s) on <strong>{{ property_address }}</strong> are <strong>{{ deadline_phrase }}</strong>.</p><table style="border-collapse:collapse;font-size:14px;margin:10px 0"><tr><td style="padding:4px 14px 4px 0;color:#6b7280">Transaction</td><td style="padding:4px 0;font-weight:600">{{ deal_number }}</td></tr><tr><td style="padding:4px 14px 4px 0;color:#6b7280">Property</td><td style="padding:4px 0;font-weight:600">{{ property_address }}</td></tr><tr><td style="padding:4px 14px 4px 0;color:#6b7280">Conditions</td><td style="padding:4px 0;font-weight:600">{{ condition_list }}</td></tr><tr><td style="padding:4px 14px 4px 0;color:#6b7280">Deadline</td><td style="padding:4px 0;font-weight:600">{{ deadline_date }}</td></tr><tr><td style="padding:4px 14px 4px 0;color:#6b7280">Days remaining</td><td style="padding:4px 0;font-weight:600">{{ days_remaining }}</td></tr></table>{{ transaction_button }}<p>{{ company_name }}</p>$old$;
